 // =======================================================
// 1) ENTRADA DO ARQUIVO
// =======================================================
const incoming = items[0];
const dataField = "file"; // nome do binário de entrada

if (!incoming.binary || !incoming.binary[dataField]) {
  throw new Error("Nenhum arquivo recebido no campo 'file'.");
}

const binary = incoming.binary[dataField];

// Buffer do arquivo
const buffer = Buffer.from(binary.data, "base64");

// Converte para texto (CSV)
const text = buffer.toString("utf8");


// =======================================================
// 2) PARSER CSV UNIVERSAL (, ; | Excel Brasileiro)
// =======================================================
function parseCSV(text) {
  const linhas = text
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l.length > 0);

  if (linhas.length === 0) return [];

  const primeiraLinha = linhas[0];

  // Detecta separador automático
  const separador =
    primeiraLinha.includes(";") ? ";" :
    primeiraLinha.includes(",") ? "," :
    ";"; // fallback Excel BR

  const header = primeiraLinha.split(separador).map(h => h.trim());

  const registros = linhas.slice(1).map(line => {
    const cols = line.split(separador);
    const obj = {};

    header.forEach((h, i) => {
      obj[h] = (cols[i] || "").trim();
    });

    return obj;
  });

  return registros;
}


// =======================================================
// 3) GERAR JSON FINAL
// =======================================================
const registros = parseCSV(text);

// Retorno no formato do n8n
return registros.map(r => ({ json: r }));

// =======================================================
// FUNÇÃO: converte "DD/MM/AAAA" → "AAAA-MM-DD"
// =======================================================
function brToIso(dateStr) {
  if (!dateStr) return null;

  // Se já estiver no formato ISO, não mexe
  if (dateStr.includes("-")) return dateStr;

  const [dia, mes, ano] = dateStr.split("/");
  return `${ano}-${mes.padStart(2, "0")}-${dia.padStart(2, "0")}`;
}


// =======================================================
// PROCESSA O CSV PARSEADO → AJUSTA DATAS
// =======================================================
return items.map(item => {
  const j = item.json;

  return {
    json: {
      ...j,
      data_mov: brToIso(j.data_mov),
      data_vencto: brToIso(j.data_vencto)  ,

    }
  };
});

